function associateTemplateTools(){return `<details class="journey-advanced"><summary>Start a sourced associate-transfer checklist</summary><form id="associate-template-form"><label>Awarding college<input name="institution" list="degree-schools" value="${esc(state.profile?.degreeInstitution||'Bellevue College')}" required maxlength="120"></label><label>Applicable catalog year<input name="catalogYear" required maxlength="30" placeholder="Confirm with your college"></label><label><input name="scope" type="checkbox" required> I understand this is the statewide September 2026 DTA guideline; I still need my college's local rules and approved course list.</label><button class="btn">Load DTA guideline checklist</button></form><p>90 quarter credits; at least 60 general education plus 30 electives; awarding-college GPA minimum 2.0. The guideline is not an AS-T, applied associate degree or a guarantee of major admission.</p><a class="journey-secondary" href="${AssociateEvidence.source}" target="_blank" rel="noopener">Official 2026 DTA guidelines PDF ↗</a></details>`}
function loadAssociateTemplate(form){const f=Object.fromEntries(new FormData(form));if(!f.scope)return toast('Review the scope before loading the guideline.');state.degreeGoals||=[];if(state.degreeGoals.length>=6)return toast('Use up to six goals.');const categories=AssociateEvidence.categories.filter(c=>c.id!=='communication').map(c=>({id:'dta-'+c.id,label:c.label,count:1,minCredits:c.minimumCredits,creditUnits:'Quarter',choices:[],minDisciplines:c.minimumDisciplines||1,labRequired:!!c.minimumLabCourses,noWithinSharing:true,source:AssociateEvidence.source,evidence:'Statewide 2026 guideline; local course eligibility entered by student/advisor'}));categories.unshift({id:'dta-composition',label:'English composition',count:1,minCredits:5,creditUnits:'Quarter',choices:[],noWithinSharing:true,source:AssociateEvidence.source},{id:'dta-communication-other',label:'Additional composition, writing or basic speaking',count:1,minCredits:5,creditUnits:'Quarter',choices:[],noWithinSharing:true,source:AssociateEvidence.source});state.degreeGoals.push({id:degreeIds(),name:f.institution+' — 2026 DTA statewide guideline',kind:'Associate — transfer / DTA',institution:f.institution,catalogYear:f.catalogYear,source:AssociateEvidence.source,preset:'dta-2026-guidelines',role:state.degreeGoals.some(g=>g.role==='primary')?'concurrent':'primary',sharing:'review',advisorConfirmed:false,requirements:categories,notes:['Statewide guideline only: verify local college adoption and catalog-year requirements. The Bellevue-specific catalog checklist is not verified.','90 quarter credits and awarding-college GPA 2.0; at least 60 general education credits. Each course is allocated once within this guideline.','Humanities, Social Science and Natural Science each require at least two disciplines; Natural Science requires a laboratory. Enter documented discipline and laboratory metadata for courses.','Humanities: at most five performance/skills credits and at most five 100-level world-language credits. These caps require separate institutional review; they are not inferred from course titles.','Flexible distribution may include humanities, social science, mathematics or natural science. Quantitative reasoning readiness, approved courses, remedial exclusions and local requirements need review.','Additional local requirements may apply. DTA does not waive selective-major admission. Apply for graduation through the awarding college.']});save();render();toast('DTA guideline loaded. Match only courses approved by your college to each category.')}
function associateMatchingTools(){const goals=(state.degreeGoals||[]).filter(g=>g.preset==='dta-2026-guidelines'),pool=degreeCoursePool();if(!goals.length)return '';return `<details class="journey-advanced" open><summary>Match documented courses to the DTA guideline</summary><p>Select only courses the awarding college lists in that category. Course titles do not establish distribution eligibility. Matching is student/advisor-entered and needs final college review.</p><form id="dta-match-form"><label>DTA category<select name="requirement">${goals.flatMap(g=>g.requirements.map(r=>`<option value="${esc(g.id+'|'+r.id)}">${esc(g.institution)} · ${esc(r.label)} · ${r.minCredits} quarter credits</option>`)).join('')}</select></label><fieldset class="degree-course-choices"><legend>Documented eligible alternatives (up to 12)</legend>${pool.filter(c=>(c.units||'Quarter')==='Quarter').map(c=>`<label><input type="checkbox" name="choice" value="${esc(MultiDegree.key(c))}"> ${esc(c.code)} · ${esc(c.institution)}</label>`).join('')||'<p>Add course alternatives or academic records first.</p>'}</fieldset><label>Official college approved-course/category source<input name="source" type="url" required placeholder="https://"></label><button class="btn">Replace category alternatives</button></form><h3>Documented course metadata</h3><p>Needed for two-discipline and lab checks. Enter the college’s discipline name; do not assume it from a course code. Source and metadata are recorded by you, not independently verified.</p>${pool.map(c=>`<div class="dta-course-metadata"><strong>${esc(c.code)} · ${esc(c.institution)}</strong><label>Discipline<input data-course-discipline="${esc(MultiDegree.key(c))}" maxlength="80" value="${esc(c.discipline||'')}" placeholder="e.g. Physics"></label><label><input type="checkbox" data-course-lab="${esc(MultiDegree.key(c))}" ${c.hasLab?'checked':''}> Includes documented laboratory</label></div>`).join('')}</details>`}
function updateDegreeMetadata(key,field,value){let c=(state.degreeCourses||[]).find(c=>MultiDegree.key(c)===key);if(!c){const row=degreeCoursePool().find(c=>MultiDegree.key(c)===key);if(!row)return;state.degreeCourses||=[];c={code:row.code,title:row.title,institution:row.institution,units:row.units,credits:row.credits,prereqs:[],coreqs:[],completed:false};state.degreeCourses.push(c)}c[field]=value;save();render()}
function installAssociates(){const before=degreePlanner;degreePlanner=()=>before().replace('<datalist id="degree-schools">',associateTemplateTools()+associateMatchingTools()+'<datalist id="degree-schools">');const beforeBind=bind;bind=()=>{beforeBind();document.querySelector('#associate-template-form')?.addEventListener('submit',e=>{e.preventDefault();loadAssociateTemplate(e.target)});document.querySelector('#dta-match-form')?.addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.target),[goalId,reqId]=form.get('requirement').split('|'),goal=state.degreeGoals.find(g=>g.id===goalId),req=goal?.requirements.find(r=>r.id===reqId),choices=form.getAll('choice'),source=form.get('source');if(!req)return;if(!choices.length||choices.length>12)return toast('Select 1–12 documented course alternatives.');if(!ProductCore.safeURL(source))return toast('Use an HTTPS college category source.');req.choices=choices;req.eligibilitySource=source;goal.edited=true;save();render()});document.querySelectorAll('[data-course-discipline]').forEach(el=>el.onchange=()=>updateDegreeMetadata(el.dataset.courseDiscipline,'discipline',el.value.trim()));document.querySelectorAll('[data-course-lab]').forEach(el=>el.onchange=()=>updateDegreeMetadata(el.dataset.courseLab,'hasLab',el.checked))}}
